    if ((primary == NULL) || (secondary == NULL) || 
        (separation_rad == NULL) || (cross_sine == NULL) || (condition_proxy == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(primary)) || (!adcs_is_finite_vec3(secondary))) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t u, v;
    if (adcs_vec3_normalize(primary, ADCS_EPS_NORM, &u) != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(secondary, ADCS_EPS_NORM, &v) != ADCS_OK) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    double dot = adcs_vec3_dot(&u, &v);
    adcs_vec3_t cross = adcs_vec3_cross(&u, &v);
    double s = adcs_vec3_norm(&cross);

    if (s <= ADCS_EPS_COLLINEAR) {
        *separation_rad = 0.0;
        *cross_sine = 0.0;
        *condition_proxy = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    *cross_sine = s;
    *separation_rad = atan2(s, dot);
    *condition_proxy = 1.0 / s;

    return ADCS_OK;
}

